# Writes result-v2.fwr, the fixture of result format version 2 (FisherWright
# 0.11.0), with assortative mating so that mate_correlation is recorded.
# Kept for provenance: the fixture must not be regenerated by later
# releases, whose seeded output may differ; the test checks it against the
# values written down in test/runtests.jl ("Result files").
#
#   julia --project=../.. make-result-v2.jl

using FisherWright, Random, Distributions

chr = [60_000, 40_000]
loci = trait_loci(chr, 30; a=MvNormal(zeros(2), [0.04 0.01; 0.01 0.04]), μ=5e-3, rng=Xoshiro(1))
fit = TraitFitness(loci; Σe=[0.5 0.1; 0.1 0.5], fitness=Directional([0.3, -0.1]))
res = fisher_wright(12, 8, chr, 1.0; mut_base=1e5, result=true, pedigree=2, fitness=fit,
    mating=Assortative(0.6), rng=Xoshiro(2))
write_result(joinpath(@__DIR__, "result-v2.fwr"), res)
